# ABOUTME: Reusable home-manager modules for this flake
# ABOUTME: Import these modules in home configurations to share common settings
{
  agentSkills = import ./agent-skills.nix;
  bat = import ./bat.nix;
  claudeCode = import ./claude-code.nix;
  delta = import ./delta.nix;
  doom = import ./doom.nix;
  direnv = import ./direnv.nix;
  fzf = import ./fzf.nix;
  git = import ./git.nix;
  herdr = import ./herdr.nix;
  mail = import ./mail.nix;
  pi = import ./pi.nix;
  tmux = import ./tmux.nix;
  twitchWatcher = import ./twitch-watcher.nix;
  zsh = import ./zsh.nix;
}

# ABOUTME: Base home-manager configuration shared across all platforms
# ABOUTME: Provides common module imports, packages, and webframp module defaults
{
  config,
  lib,
  pkgs,
  inputs,
  outputs,
  ...
}: {
  imports =
    [
      ./programs.nix
      inputs.shelley-herdr.homeManagerModules.default
    ]
    ++ (with outputs.homeManagerModules; [
      zsh
      agentSkills
      bat
      claudeCode
      delta
      direnv
      doom
      fzf
      git
      herdr
      mail
      pi
      tmux
      twitchWatcher
    ]);

  nix = {
    package = lib.mkDefault pkgs.nix;
    settings = {
      experimental-features = ["nix-command" "flakes"];
      warn-dirty = false;
    };
  };

  # Note: nixpkgs.config is set per-host for standalone home-manager configs.
  # NixOS hosts using useGlobalPkgs inherit nixpkgs config from NixOS.
  programs.home-manager.enable = true;

  # Home defaults with platform-appropriate paths
  home = {
    username = lib.mkDefault "sme";
    homeDirectory = lib.mkDefault (
      if pkgs.stdenv.hostPlatform.isDarwin
      then "/Users/${config.home.username}"
      else "/home/${config.home.username}"
    );
    stateVersion = lib.mkDefault "24.05";
    # Common packages for all platforms (hosts can add more via home.packages)
    packages = import ./packages.nix {inherit lib pkgs;};
  };

  home.file.".local/bin/tmux-jump-bell" = {
    source = ../shared/includes/tmux-jump-bell.sh;
    executable = true;
  };

  # Shared webframp module configuration
  # Hosts can override specific options as needed
  webframp.agentSkills = {
    enable = true;
    skills = ["writing-editorial" "hostile-code-analysis" "pre-push-review" "triage"];
  };
  webframp.bat.enable = true;
  webframp.claudeCode.enable = true;
  webframp.doom.enable = true;
  webframp.herdr.enable = true;
  programs.shelley-herdr.enable = true;
  webframp.pi.enable = true;
  webframp.delta.enable = true;
  webframp.direnv = {
    enable = true;
    whitelist = ["~/src/o11n"];
  };
  webframp.fzf.enable = true;
  webframp.git = {
    enable = true;
    extraIncludes = [{path = "~/.config/git/forge.conf";}];
  };
  webframp.tmux.enable = true;
  webframp.zsh.enable = true;

  # Linux-specific defaults (can be overridden by hosts)
  webframp.tmux.terminal = lib.mkIf pkgs.stdenv.hostPlatform.isLinux "tmux-256color";
  webframp.zsh.enableVterm = lib.mkIf pkgs.stdenv.hostPlatform.isLinux (lib.mkDefault false);

  # Prune stale zcompdump files weekly (they accumulate per-PID on NixOS rebuilds)
  systemd.user.services.zcompdump-cleanup = lib.mkIf pkgs.stdenv.hostPlatform.isLinux {
    Unit.Description = "Remove stale zcompdump files older than 7 days";
    Service = {
      Type = "oneshot";
      ExecStart = "${pkgs.findutils}/bin/find ${config.home.homeDirectory} -maxdepth 1 -name '.zcompdump.*' -mtime +7 -delete";
    };
  };
  systemd.user.timers.zcompdump-cleanup = lib.mkIf pkgs.stdenv.hostPlatform.isLinux {
    Unit.Description = "Weekly zcompdump cleanup";
    Timer = {
      OnCalendar = "weekly";
      Persistent = true;
    };
    Install.WantedBy = ["timers.target"];
  };
}

# ABOUTME: Home-manager configuration for bluestreak (macOS Apple Silicon)
# ABOUTME: Primary workstation with full development environment
{
  outputs,
  lib,
  pkgs,
  ...
}: let
  gpgKey = "REDACTED";
in {
  imports = [./shared/base.nix];

  # macOS-specific nix settings
  nix.settings.auto-optimise-store = false;

  nixpkgs = {
    config.allowUnfreePredicate = _: true;
    overlays = [outputs.overlays.additions outputs.overlays.modifications];
  };

  home = {
    username = "sme";
    homeDirectory = "/Users/sme";
    stateVersion = "24.05";
    # Extra packages beyond base.nix (lists merge automatically)
    packages = with pkgs; [
      aws-doctor # custom package
      curl # macOS ships an old system curl; gptel-bedrock requires >= 8.9
      devcontainer
      emacs-lsp-booster
      mcp-k8s-go # https://github.com/strowk/mcp-k8s-go
    ];
  };

  # Bluestreak-specific webframp overrides
  webframp.git.credentialHelper = "!pass-git-helper $@";
  webframp.tmux.enableOrgCapture = true;

  webframp.zsh = {
    enableVterm = true;

    extraShellAliases = {
      # Home-manager
      yay = "home-manager switch --flake .#sme@bluestreak";
      yayb = "brew update && brew upgrade && brew cleanup";
      news = "home-manager news --flake .";
      nixcleanup = "nix profile wipe-history --older-than 14d && nix-collect-garbage";

      # macOS-specific
      docker = "podman";

      # Doom Emacs
      doom = "~/.config/emacs/bin/doom";

      # Kubernetes
      k = "kubectl";
      kn = "kswitch ns";
      ks = "kswitch";
      kx = "kswitch";
    };

    extraEnvVars = ''
      export PODMAN_COMPOSE_WARNING_LOGS=false
      # homebrew is not managed via nix, but a necessary evil on macOS
      [ -d /opt/homebrew/bin ] && export PATH="/opt/homebrew/bin:$PATH"
      [ -d "$HOME/.local/bin" ] && export PATH="$HOME/.local/bin:$PATH"
    '';

    extraZplugPlugins = [
      {
        # https://github.com/wfxr/forgit
        name = "webframp/zsh-forgit";
        tags = ["defer:0"];
      }
      {
        # https://github.com/hlissner/zsh-autopair
        name = "webframp/zsh-autopair";
        tags = ["defer:2"];
      }
      {
        name = "webframp/zsh-plugins";
        tags = ["defer:2" "use:rationalize-dot.plugin.zsh"];
      }
      {name = "webframp/zsh-you-should-use";}
      {
        name = "plugins/kubectl";
        tags = ["defer:2" "from:oh-my-zsh"];
      }
    ];
  };

  # programs.git-cliff.enable = true;

  programs.gpg = {
    enable = true;
    settings = {
      default-key = gpgKey;
      no-tty = true;
      use-agent = true;
    };
  };

  services.gpg-agent = {
    enable = true;
    defaultCacheTtl = 84000;
    maxCacheTtl = 84000;
    pinentry.package = pkgs.pinentry_mac;
  };

  # doom emacs setup is still manual
  programs.emacs = {
    enable = true;
    package = pkgs.emacs.override {withNativeCompilation = true;};
  };

  programs.keychain = {
    enable = true;
    extraFlags = ["--nogui" "--noask" "--quiet"];
    keys = ["id_ed25519" gpgKey];
  };

  services.home-manager.autoExpire = {
    enable = true;
    frequency = "weekly";
    timestamp = "-7 days";
  };
}

